const body = $input.first().json.body || $input.first().json;
let machineId = (body.machine_id || '').trim();
let limit = parseInt(body.limit || 20);
if (isNaN(limit) || limit < 1) limit = 20;
if (limit > 200) limit = 200;
// 安全验证：只允许字母数字连字符
machineId = machineId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { machine_id: machineId, limit: limit } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
const count = arr.length;
let text = '';
if (count === 0) {
  text = '未找到告警记录';
} else {
  text = arr.map((r, i) => `${i+1}. ${r.event_time || ''} ${r.event_name || ''} ${r.event_value || ''}`).join('\n');
}
return { json: { alarms: arr, count: count, summary: text } };
